Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='shortdockeepslaws', at=datetime(2026, 11, 25, 0, 0, 0), actor='assistant', title='A doc cut for repeating the signature or the spec keeps every law, inverse, precondition, no-op case and cost', body='When a doc comment is shortened because it repeats the signature or the specification, check what it stated that the signature does not state: each law, each inverse, each precondition, each case that does nothing, and each cost. Keep every one of these in the shorter doc, and cut only the words that restate the types.', rationale='A reader who cannot see the specification relies on the doc for the laws and the cost. A cut that drops one of them turns a documented contract into a guess, and no test reports the loss.', supersedes=()))